# kaliru plugin layer: mirror of Kalico klippy.util (generated by tools/gen_mirror.py)
import _k

import fcntl
import os
import termios

def fix_sigint():
    return _k.fcall(7407)

def set_nonblock(fd):
    fcntl.fcntl(
        fd, fcntl.F_SETFL, fcntl.fcntl(fd, fcntl.F_GETFL) | os.O_NONBLOCK
    )

def clear_hupcl(fd):
    attrs = termios.tcgetattr(fd)
    attrs[2] = attrs[2] & ~termios.HUPCL
    try:
        termios.tcsetattr(fd, termios.TCSADRAIN, attrs)
    except termios.error:
        pass

def create_pty(ptyname):
    return _k.fcall(7410, ptyname)

def dump_file_stats(build_dir, filename):
    return _k.fcall(7411, build_dir, filename)

def dump_mcu_build():
    return _k.fcall(7412)

def get_cpu_info():
    return _k.fcall(7413)

def get_version_from_file(klippy_src):
    try:
        with open(os.path.join(klippy_src, ".version")) as h:
            return h.read().rstrip()
    except IOError:
        pass
    return "?"

def _get_repo_info(gitdir):
    return _k.fcall(7415, gitdir)

def get_git_version(from_file=True):
    return _k.fcall(7416, from_file)

fix_sigint()

__getattr__ = _k.module_getattr(__name__)
